 "content": "def transform(grid):
    # Move the horizontal bars to the top-left and form a diagonal chain.
    # Bars are ordered by original horizontal position, top-to-bottom/rightwards.
    h, w = len(grid), len(grid[0])
    colors = []
    for c in range(1, 10):
        cells = [(r, j) for r in range(h) for j in range(w) if grid[r][j] == c]
        if cells:
            colors.append((min(j for r, j in cells), c,
                           max(r for r, j in cells)-min(r for r, j in cells)+1,
                           max(j for r, j in cells)-min(j for r, j in cells)+1))
    colors.sort()
    out = [[0]*w for _ in range(h)]
    for k, (_, c, hh, ww) in enumerate(colors):
        for dr in range(hh):
            for dc in range(ww):
                if k+dr < h and k+dc < w:
                    out[k+dr][k+dc] = c
    return out

